PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "media" ("id" integer primary key autoincrement not null, "model_type" varchar not null, "model_id" integer not null, "uuid" varchar, "collection_name" varchar not null, "name" varchar not null, "file_name" varchar not null, "mime_type" varchar, "disk" varchar not null, "conversions_disk" varchar, "size" integer not null, "manipulations" text not null, "custom_properties" text not null, "generated_conversions" text not null, "responsive_images" text not null, "order_column" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "business_count" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "countries" ("id" integer primary key autoincrement not null, "name" varchar not null, "iso2" varchar);
CREATE TABLE IF NOT EXISTS "states" ("id" integer primary key autoincrement not null, "country_id" integer not null, "name" varchar not null, foreign key("country_id") references "countries"("id") on update cascade);
CREATE TABLE IF NOT EXISTS "business_hours" ("id" integer primary key autoincrement not null, "business_id" integer not null, "day_of_week" integer not null, "open_time" time, "close_time" time, "is_closed" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("business_id") references "businesses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "business_awards" ("id" integer primary key autoincrement not null, "business_id" integer not null, "title" varchar not null, "year" integer, "created_at" datetime, "updated_at" datetime, foreign key("business_id") references "businesses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "business_promotions" ("id" integer primary key autoincrement not null, "business_id" integer not null, "title" varchar not null, "description" text, "discount_text" varchar, "valid_until" date, "created_at" datetime, "updated_at" datetime, foreign key("business_id") references "businesses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "favorites" ("id" integer primary key autoincrement not null, "user_id" integer not null, "business_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("business_id") references "businesses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "business_views" ("id" integer primary key autoincrement not null, "user_id" integer, "business_id" integer not null, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("user_id") references "users"("id") on delete cascade, foreign key("business_id") references "businesses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sponsored_ads" ("id" integer primary key autoincrement not null, "business_id" integer, "title" varchar not null, "description" text, "cta_text" varchar not null default 'Learn More', "cta_url" varchar, "is_active" tinyint(1) not null default '1', "order" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("business_id") references "businesses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "businesses" ("id" integer primary key autoincrement not null, "user_id" integer not null, "category_id" integer not null, "name" varchar not null, "slug" varchar not null, "description" text, "phone" varchar, "email" varchar, "website" varchar, "address" varchar, "city" varchar, "state_id" integer, "country_id" integer, "country" varchar, "latitude" numeric, "longitude" numeric, "is_verified" tinyint(1) not null default ('0'), "verified_at" datetime, "is_featured" tinyint(1) not null default ('0'), "is_24_7" tinyint(1) not null default ('0'), "status" varchar not null default ('active'), "staff_size" varchar, "years_active" integer, "avg_rating" numeric not null default ('0'), "total_reviews" integer not null default ('0'), "views_count" integer not null default ('0'), "saves_count" integer not null default ('0'), "favorites_count" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "verified_by" integer, foreign key("country_id") references countries("id") on delete cascade on update no action, foreign key("state_id") references states("id") on delete set null on update no action, foreign key("category_id") references categories("id") on delete cascade on update no action, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("verified_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "activity_logs" ("id" integer primary key autoincrement not null, "type" varchar not null, "title" varchar not null, "description" text not null, "status" varchar, "icon" varchar, "user_id" integer, "business_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, foreign key("business_id") references "businesses"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "reports" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "admin_id" integer not null, "title" varchar not null, "metrics" text not null, "status" varchar check ("status" in ('draft', 'submitted', 'approved')) not null default 'submitted', "created_at" datetime, "updated_at" datetime, "description" text, "period_start" date, "period_end" date, foreign key("sbo_id") references "sbos"("id") on delete cascade, foreign key("admin_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "purchase_orders" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "category_id" integer not null, "title" varchar not null, "description" text not null, "document_path" varchar, "budget" numeric, "order_deadline" date, "status" varchar not null default ('draft'), "completed_at" datetime, "created_at" datetime, "updated_at" datetime, "awarded_bid_id" integer, "quantity" varchar, "required_documents" text, "terms" text, "request_type" varchar not null default 'product', "unit_specification" varchar, "delivery_location" varchar, "service_scope" text, "service_duration" varchar, "required_expertise" varchar, "award_note" text, "visibility" varchar not null default 'public', "advertised_at" date, "briefing_at" datetime, "briefing_link" varchar, "briefing_location" varchar, "briefing_mandatory" tinyint(1) not null default '0', "inquiry_opens_at" date, "inquiry_closes_at" date, "inquiry_responses_at" date, "final_selection_at" date, foreign key("category_id") references categories("id") on delete cascade on update no action, foreign key("sbo_id") references sbos("id") on delete cascade on update no action, foreign key("awarded_bid_id") references "purchase_order_bids"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "ad_placements" ("id" integer primary key autoincrement not null, "slot" varchar not null, "title" varchar not null, "cta_text" varchar not null default 'Learn More', "cta_url" varchar, "priority" integer not null default '0', "starts_at" datetime, "ends_at" datetime, "is_active" tinyint(1) not null default '1', "impressions" integer not null default '0', "clicks" integer not null default '0', "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "ad_events" ("id" integer primary key autoincrement not null, "ad_placement_id" integer not null, "type" varchar not null, "ip_hash" varchar, "user_agent" varchar, "created_at" datetime, foreign key("ad_placement_id") references "ad_placements"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "cities" ("id" integer primary key autoincrement not null, "state_id" integer not null, "name" varchar not null, foreign key("state_id") references "states"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "sbo_compliance_documents" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "compliance_document_type_id" integer not null, "status" varchar not null default 'pending', "rejection_reason" text, "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("sbo_id") references "sbos"("id") on delete cascade, foreign key("compliance_document_type_id") references "compliance_document_types"("id") on delete cascade, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_payment_proofs" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "status" varchar not null default 'pending', "rejection_reason" text, "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("sbo_id") references "sbos"("id") on delete cascade, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "compliance_document_types" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "is_required" tinyint(1) not null default ('1'), "is_active" tinyint(1) not null default ('1'), "sort_order" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "country_id" integer, "registry_authority" varchar, "source_url" varchar, "source_note" text, "is_seeded" tinyint(1) not null default '0', "needs_admin_review" tinyint(1) not null default '0', foreign key("country_id") references "countries"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_fee_bands" ("id" integer primary key autoincrement not null, "structure" varchar not null, "max_equity" integer, "fee" integer not null, "label" varchar not null, "sort_order" integer not null default ('0'), "is_active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "country_id" integer, foreign key("country_id") references "countries"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_capital_types" ("id" integer primary key autoincrement not null, "structure" varchar not null, "key" varchar not null, "label" varchar not null, "sort_order" integer not null default ('0'), "is_active" tinyint(1) not null default ('1'), "created_at" datetime, "updated_at" datetime, "country_id" integer, "scope_key" varchar not null default 'global', foreign key("country_id") references "countries"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_fee_settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" varchar, "created_at" datetime, "updated_at" datetime, "country_id" integer, "scope_key" varchar not null default 'global', foreign key("country_id") references "countries"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "zones" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar, "code" varchar not null, "pastor_name" varchar, "pastor_email" varchar, "is_active" tinyint(1) not null default '1', "sent_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sbos" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "rc_number" varchar, "tax_number" varchar, "business_type" varchar, "category" varchar, "region" varchar, "established_at" date, "website" varchar, "staff_count" integer, "business_model" varchar, "primary_contact_name" varchar, "primary_contact_email" varchar, "phone" varchar, "kingschat_handle" varchar, "directors" text, "description" text, "is_active" tinyint(1) not null default ('1'), "created_by" integer, "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('active'), "legal_structure" varchar, "address" varchar, "city" varchar, "state" varchar, "country" varchar, "premise_type" varchar, "owner_surname" varchar, "owner_first_name" varchar, "owner_country" varchar, "owner_residential_address" varchar, "church_zone" varchar, "local_assembly" varchar, "years_as_member" integer, "zonal_pastor" varchar, "local_pastor" varchar, "application_id" varchar, "received_by" integer, "date_received" datetime, "verification_status" varchar not null default ('pending'), "approved_by" integer, "date_approved" datetime, "moc_registration_number" varchar, "decline_reason" text, "social_links" text, "info_request" text, "resubmitted_at" datetime, "code_of_conduct_agreed_at" datetime, "documents_status" varchar not null default ('pending'), "payment_status" varchar not null default ('unpaid'), "documents_compliant_at" datetime, "payment_confirmed_at" datetime, "verified_notified_at" datetime, "share_structure" varchar, "share_capital_type" varchar, "issued_shares_volume" integer, "per_share_value" numeric, "calculated_fee" integer, "fee_band" varchar, "payment_reference" varchar, "payment_submitted_at" datetime, "country_id" integer, "zone_id" integer, "referred_via_code" varchar, "industry" varchar, "trading_name" varchar, "registration_number" varchar, "latitude" numeric, "longitude" numeric, "geocoded_at" datetime, "geocoded_address" varchar, foreign key("country_id") references countries("id") on delete set null on update no action, foreign key("created_by") references users("id") on delete set null on update no action, foreign key("received_by") references users("id") on delete set null on update no action, foreign key("approved_by") references users("id") on delete set null on update no action, foreign key("zone_id") references "zones"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "firstname" varchar not null, "lastname" varchar not null, "name" varchar not null, "phone" varchar, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default ('user'), "permissions" text, "suspended_at" datetime, "suspended_by" integer, "suspension_reason" varchar, "profile_photo_path" varchar, "kc_handle" varchar, "admin_page_permissions" text, "preferences" text, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" datetime, "password_changed_at" datetime, "last_login_at" datetime, "last_login_ip" varchar, "last_login_user_agent" varchar, "locale" varchar, foreign key("suspended_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_payment_transactions" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "provider" varchar not null default 'espees', "local_reference" varchar not null, "provider_reference" varchar, "amount" integer not null, "currency" varchar not null, "gateway_status" varchar not null default 'initiated', "review_status" varchar not null default 'none', "raw_payload" text, "rejection_reason" text, "reviewed_by" integer, "submitted_at" datetime, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("sbo_id") references "sbos"("id") on delete cascade, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "ad_rate_cards" ("id" integer primary key autoincrement not null, "slot" varchar not null, "label" varchar not null, "duration_days" integer not null, "price" integer not null, "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "ad_campaigns" ("id" integer primary key autoincrement not null, "user_id" integer, "ad_rate_card_id" integer, "ad_placement_id" integer, "slot" varchar not null, "title" varchar not null, "cta_text" varchar not null default 'Learn More', "cta_url" varchar not null, "duration_days" integer not null, "price" integer not null, "currency" varchar not null default 'Espees', "desired_start_date" date, "starts_at" datetime, "ends_at" datetime, "status" varchar not null default 'pending_payment', "payment_reference" varchar, "payment_confirmed_at" datetime, "rejection_reason" text, "approved_by" integer, "approved_at" datetime, "rejected_by" integer, "rejected_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, foreign key("ad_rate_card_id") references "ad_rate_cards"("id") on delete set null, foreign key("ad_placement_id") references "ad_placements"("id") on delete set null, foreign key("approved_by") references "users"("id") on delete set null, foreign key("rejected_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "ad_payment_transactions" ("id" integer primary key autoincrement not null, "ad_campaign_id" integer not null, "provider" varchar not null default 'espees', "local_reference" varchar not null, "provider_reference" varchar, "amount" integer not null, "currency" varchar not null, "gateway_status" varchar not null default 'initiated', "review_status" varchar not null default 'none', "raw_payload" text, "submitted_at" datetime, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("ad_campaign_id") references "ad_campaigns"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "feedback_submissions" ("id" integer primary key autoincrement not null, "user_id" integer, "name" varchar not null, "email" varchar not null, "kc_handle" varchar not null, "feedback_type" varchar not null, "priority" varchar not null default 'normal', "subject" varchar not null, "message" text not null, "page_url" varchar, "status" varchar not null default 'new', "admin_notes" text, "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_seals" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "issued_number" varchar not null, "issued_year" varchar not null, "serial_number" varchar not null, "image_path" varchar not null, "issued_at" datetime not null, "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'provisional', "verified_at" datetime, foreign key("sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_connections" ("id" integer primary key autoincrement not null, "requester_sbo_id" integer not null, "recipient_sbo_id" integer not null, "status" varchar not null default 'pending', "responded_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("requester_sbo_id") references "sbos"("id") on delete cascade, foreign key("recipient_sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_conversations" ("id" integer primary key autoincrement not null, "connection_id" integer, "purchase_order_id" integer, "created_by_sbo_id" integer not null, "type" varchar not null default 'direct', "last_message_at" datetime, "created_at" datetime, "updated_at" datetime, "industry" varchar, foreign key("connection_id") references "sbo_connections"("id") on delete set null, foreign key("purchase_order_id") references "purchase_orders"("id") on delete set null, foreign key("created_by_sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_conversation_participants" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "sbo_id" integer not null, "last_read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("conversation_id") references "sbo_conversations"("id") on delete cascade, foreign key("sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_messages" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "sbo_id" integer not null, "user_id" integer not null, "body" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, "detected_locale" varchar, "detected_at" datetime, foreign key("conversation_id") references "sbo_conversations"("id") on delete cascade, foreign key("sbo_id") references "sbos"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "purchase_order_invites" ("id" integer primary key autoincrement not null, "purchase_order_id" integer not null, "invited_sbo_id" integer not null, "invited_by_sbo_id" integer not null, "status" varchar not null default 'pending', "responded_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("purchase_order_id") references "purchase_orders"("id") on delete cascade, foreign key("invited_sbo_id") references "sbos"("id") on delete cascade, foreign key("invited_by_sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_network_reports" ("id" integer primary key autoincrement not null, "reporter_sbo_id" integer not null, "reported_sbo_id" integer, "purchase_order_id" integer, "message_id" integer, "reason" varchar not null, "details" text, "status" varchar not null default 'open', "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("reporter_sbo_id") references "sbos"("id") on delete cascade, foreign key("reported_sbo_id") references "sbos"("id") on delete set null, foreign key("purchase_order_id") references "purchase_orders"("id") on delete set null, foreign key("message_id") references "sbo_messages"("id") on delete set null, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "purchase_order_bids" ("id" integer primary key autoincrement not null, "purchase_order_id" integer not null, "user_id" integer not null, "business_id" integer, "proposal" text, "attachment_path" varchar, "status" varchar not null default ('pending'), "submitted_at" datetime, "created_at" datetime, "updated_at" datetime, "bidder_sbo_id" integer, "details" text, foreign key("business_id") references businesses("id") on delete cascade on update no action, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("purchase_order_id") references purchase_orders("id") on delete cascade on update no action, foreign key("bidder_sbo_id") references "sbos"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "advertising_inquiries" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "kc_handle" varchar not null, "email" varchar not null, "ad_location" varchar not null, "message" text not null, "status" varchar not null default 'new', "admin_notes" text, "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "business_reports" ("id" integer primary key autoincrement not null, "business_id" integer not null, "user_id" integer not null, "reason" varchar not null, "details" text, "contact_requested" tinyint(1) not null default '0', "status" varchar not null default 'open', "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("business_id") references "businesses"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "inventory_order_items" ("id" integer primary key autoincrement not null, "inventory_order_id" integer not null, "business_product_id" integer, "product_name" varchar not null, "quantity" integer not null, "unit_price" integer not null, "line_total" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("inventory_order_id") references "inventory_orders"("id") on delete cascade, foreign key("business_product_id") references "business_products"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "business_products" ("id" integer primary key autoincrement not null, "business_id" integer, "name" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime, "sku" varchar, "retail_price" integer not null default ('0'), "bulk_price" integer not null default ('0'), "bulk_min_quantity" integer not null default ('1'), "stock_quantity" integer not null default ('0'), "low_stock_threshold" integer not null default ('0'), "is_active" tinyint(1) not null default ('1'), "code" varchar, "category" varchar, "size" varchar, "colour" varchar, foreign key("business_id") references businesses("id") on delete cascade on update no action);
CREATE TABLE IF NOT EXISTS "inventory_orders" ("id" integer primary key autoincrement not null, "business_id" integer, "created_by" integer, "reference" varchar not null, "customer_name" varchar, "customer_phone" varchar, "customer_email" varchar, "price_type" varchar not null default ('retail'), "status" varchar not null default ('pending'), "total_amount" integer not null default ('0'), "notes" text, "paid_by" integer, "paid_at" datetime, "cancelled_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("paid_by") references users("id") on delete set null on update no action, foreign key("created_by") references users("id") on delete set null on update no action, foreign key("business_id") references businesses("id") on delete cascade on update no action);
CREATE TABLE IF NOT EXISTS "support_enquiries" ("id" integer primary key autoincrement not null, "user_id" integer, "sbo_id" integer, "first_name" varchar not null, "last_name" varchar not null, "sbo_number" varchar, "subject" varchar not null, "message" text not null, "status" varchar not null default ('open'), "admin_response" text, "responded_by" integer, "responded_at" datetime, "escalated_by" integer, "escalated_at" datetime, "done_by" integer, "done_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("sbo_id") references sbos("id") on delete set null on update no action, foreign key("responded_by") references users("id") on delete set null on update no action, foreign key("escalated_by") references users("id") on delete set null on update no action, foreign key("done_by") references users("id") on delete set null on update no action, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "purchase_order_questions" ("id" integer primary key autoincrement not null, "purchase_order_id" integer not null, "user_id" integer, "sbo_id" integer, "title" varchar, "body" text not null, "answer" text, "answered_by" integer, "answered_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("purchase_order_id") references "purchase_orders"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null, foreign key("sbo_id") references "sbos"("id") on delete set null, foreign key("answered_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "purchase_order_documents" ("id" integer primary key autoincrement not null, "purchase_order_id" integer not null, "section" varchar not null default 'project', "name" varchar not null, "path" varchar not null, "mime" varchar, "size" integer, "uploaded_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("purchase_order_id") references "purchase_orders"("id") on delete cascade, foreign key("uploaded_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_views" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "viewer_id" integer, "viewer_hash" varchar, "viewed_at" datetime not null, foreign key("sbo_id") references "sbos"("id") on delete cascade, foreign key("viewer_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "sbo_conversation_stars" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("conversation_id") references "sbo_conversations"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_services" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "title" varchar not null, "body" text, "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_opening_hours" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "day_of_week" integer not null, "opens_at" time, "closes_at" time, "is_closed" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_message_translations" ("id" integer primary key autoincrement not null, "message_id" integer not null, "locale" varchar not null, "body" text not null, "source_locale" varchar, "provider" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("message_id") references "sbo_messages"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "sbo_addresses" ("id" integer primary key autoincrement not null, "sbo_id" integer not null, "label" varchar, "address" varchar, "city" varchar, "state" varchar, "country" varchar, "country_code" varchar, "latitude" numeric, "longitude" numeric, "is_primary" tinyint(1) not null default '0', "position" integer not null default '0', "created_at" datetime, "updated_at" datetime, "geocoded_address" varchar, "geocoded_at" datetime, foreign key("sbo_id") references "sbos"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "subscribers" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "source" varchar not null default 'home_rail', "unsubscribed_at" datetime, "user_id" integer, "ip_address" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "reviews" ("id" integer primary key autoincrement not null, "business_id" integer, "user_id" integer not null, "rating" integer not null, "comment" text, "created_at" datetime, "updated_at" datetime, "sbo_id" integer, foreign key("sbo_id") references sbos("id") on delete cascade on update no action, foreign key("business_id") references businesses("id") on delete cascade on update no action, foreign key("user_id") references users("id") on delete cascade on update no action);
