INSERT INTO sbo_messages VALUES(10,1,124,105,'Hello — saw your listing in the registry. Do you handle cold-chain deliveries?','2026-08-05 18:08:14','2026-08-05 17:33:14','2026-08-05 17:33:14',NULL,NULL);
INSERT INTO sbo_messages VALUES(11,1,123,104,'We do. Lagos to Abuja twice a week, refrigerated up to 2 tonnes.','2026-08-05 18:08:14','2026-08-05 17:40:14','2026-08-07 09:19:48','en','2026-08-07 09:19:48');
INSERT INTO sbo_messages VALUES(12,1,124,105,'That could work for us. What lead time do you need on a booking?','2026-08-05 18:08:14','2026-08-05 17:47:14','2026-08-05 17:47:14',NULL,NULL);
INSERT INTO sbo_messages VALUES(13,1,123,104,'Three working days for a standing slot, same week if there is spare capacity.','2026-08-05 18:08:14','2026-08-05 17:54:14','2026-08-07 09:19:48','en','2026-08-07 09:19:48');
INSERT INTO sbo_messages VALUES(14,1,124,105,'Perfect. I will send over the volumes this afternoon.',NULL,'2026-08-05 18:01:14','2026-08-05 18:01:14',NULL,NULL);
INSERT INTO sbo_messages VALUES(15,12,21,3,'hi',NULL,'2026-08-05 23:11:56','2026-08-05 23:11:56',NULL,NULL);
